const request = $json ?? {};
const headers = (request && typeof request === 'object' && request.headers && typeof request.headers === 'object') ? request.headers : {};
const body = (request && typeof request === 'object' && request.body && typeof request.body === 'object') ? request.body : request;

function isTruthy(value) {
  if (value === undefined || value === null) return false;
  const v = String(value).trim().toLowerCase();
  return ['1', 'true', 'yes', 'y', 'on'].includes(v);
}

function getHeader(name) {
  const lower = name.toLowerCase();
  if (headers[lower] !== undefined) return headers[lower];
  if (headers[name] !== undefined) return headers[name];
  const key = Object.keys(headers).find((k) => k.toLowerCase() === lower);
  return key ? headers[key] : undefined;
}

function trimSlash(value) {
  return String(value || '').replace(/\/+$/, '');
}

function error(status, message, extra = {}) {
  return [{
    json: {
      ok: false,
      status_code: status,
      error: message,
      ...extra
    }
  }];
}

function asArray(value) {
  if (Array.isArray(value)) return value;
  if (value === undefined || value === null) return [];
  if (typeof value === 'string') {
    return value.split(',').map((v) => v.trim()).filter(Boolean);
  }
  return [];
}

function yyyymmUtcNow() {
  const d = new Date();
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  return `${y}-${m}`;
}

const realm = String(body.realm || body.tenant || $env.N8N_REALM || 'default').trim() || 'default';
const period = String(body.period || yyyymmUtcNow()).trim() || yyyymmUtcNow();
const practiceKeys = asArray(body.practice_keys || body.practiceKeys);
const services = Array.isArray(body.services) ? body.services : [];

const dryRun = isTruthy(body.dry_run) || isTruthy(body.dryRun) || isTruthy($env.ITSM_PRACTICE_REVIEW_DRY_RUN) || isTruthy($env.DRY_RUN);

const expectedToken = String($env.ITSM_PRACTICE_REVIEW_WEBHOOK_TOKEN || '').trim();
if (expectedToken) {
  const got = String(getHeader('x-webhook-token') || '').trim();
  if (got !== expectedToken) {
    return error(401, 'invalid webhook token');
  }
}

const practiceCatalog = {
  service_design: {
    title: 'サービス設計レビュー',
    doc: 'docs/service_management/11_service_design.md'
  },
  service_continuity: {
    title: 'サービス継続レビュー',
    doc: 'docs/service_management/10_service_continuity_management.md'
  },
  service_configuration: {
    title: 'サービス構成レビュー',
    doc: 'docs/service_management/07_service_configuration_management.md'
  },
  service_validation_testing: {
    title: '妥当性確認/テストレビュー',
    doc: 'docs/service_management/12_service_validation_and_testing.md'
  },
  change_enablement: {
    title: '変更レビュー',
    doc: 'docs/service_management/06_change_enablement.md'
  },
  service_financial: {
    title: 'サービス財務レビュー',
    doc: 'docs/service_management/14_service_financial_management.md'
  }
};

const selectedPracticeKeys = practiceKeys.length ? practiceKeys : Object.keys(practiceCatalog);
const invalidKeys = selectedPracticeKeys.filter((k) => !practiceCatalog[k]);
if (invalidKeys.length) {
  return error(400, 'invalid practice_keys', { invalid_keys: invalidKeys, allowed: Object.keys(practiceCatalog) });
}

function required(value, name) {
  if (value === undefined || value === null || String(value).trim() === '') {
    throw new Error(`${name} is required`);
  }
  return value;
}

const gitlabApiBase = trimSlash(
  body.gitlab_api_base_url ||
  body.GITLAB_API_BASE_URL ||
  $env.GITLAB_API_BASE_URL ||
  $env.N8N_GITLAB_API_BASE_URL ||
  ''
);

const gitlabToken = String(
  $env.GITLAB_TOKEN ||
  $env.N8N_GITLAB_TOKEN ||
  $env.GITLAB_ADMIN_TOKEN ||
  ''
);

const projectRef = String(
  body.gitlab_project_path ||
  body.GITLAB_PROJECT_PATH ||
  $env.GITLAB_PROJECT_PATH ||
  $env.N8N_GITLAB_PROJECT_PATH ||
  ''
).trim() || `${realm}/service-management`;

let gitlabBaseUrl = trimSlash(body.gitlab_base_url || body.GITLAB_BASE_URL || $env.GITLAB_BASE_URL || '');
if (!gitlabBaseUrl && gitlabApiBase) {
  gitlabBaseUrl = gitlabApiBase.replace(/\/api\/v4\/?$/, '');
}

if (!dryRun) {
  try {
    required(gitlabApiBase, 'GITLAB_API_BASE_URL');
    required(gitlabToken, 'GITLAB_TOKEN');
    required(projectRef, 'GITLAB_PROJECT_PATH');
  } catch (e) {
    return error(424, String(e.message || e));
  }
}

const httpRequest = this.helpers.httpRequest;
const projectEncoded = encodeURIComponent(projectRef);

async function listOpenIssuesBySearch(search) {
  if (dryRun) return [];
  const url = `${gitlabApiBase}/projects/${projectEncoded}/issues`;
  const issues = await httpRequest({
    method: 'GET',
    url,
    qs: { state: 'opened', search: String(search || ''), per_page: 50 },
    json: true,
    headers: { 'PRIVATE-TOKEN': gitlabToken }
  });
  return Array.isArray(issues) ? issues : [];
}

async function createIssue(title, description, labels) {
  if (dryRun) {
    return { ok: true, dry_run: true, title, labels, issue_url: null };
  }
  const url = `${gitlabApiBase}/projects/${projectEncoded}/issues`;
  const payload = {
    title,
    description,
    labels: labels.join(',')
  };
  const created = await httpRequest({
    method: 'POST',
    url,
    json: true,
    body: payload,
    headers: { 'PRIVATE-TOKEN': gitlabToken, 'Content-Type': 'application/json' }
  });
  return { ok: true, dry_run: false, title, labels, issue_url: created?.web_url || null, issue_iid: created?.iid || null };
}

function buildLinks(svc, practice) {
  const orgId = String(svc.org_id || svc.orgId || '').trim();
  const serviceId = String(svc.service_id || svc.serviceId || '').trim();
  const links = {};
  if (gitlabBaseUrl && orgId && serviceId) {
    links.cmdb = `${gitlabBaseUrl}/${projectRef}/-/blob/main/cmdb/${encodeURIComponent(orgId)}/${encodeURIComponent(serviceId)}.md`;
  }
  if (gitlabBaseUrl && practice?.doc) {
    links.practice_doc = `${gitlabBaseUrl}/${projectRef}/-/blob/main/${practice.doc}`;
  }
  if (gitlabBaseUrl) {
    links.usecase_guide = `${gitlabBaseUrl}/${projectRef}/-/blob/main/docs/usecases/usecase_guide.md`;
  }
  return links;
}

function buildDescription(svc, practice) {
  const cmdbId = String(svc.cmdb_id || svc.cmdbId || '').trim();
  const orgId = String(svc.org_id || svc.orgId || '').trim();
  const serviceId = String(svc.service_id || svc.serviceId || '').trim();
  const serviceName = String(svc.service_name || svc.serviceName || '').trim();
  const links = buildLinks(svc, practice);

  const lines = [];
  lines.push(`## 対象`);
  lines.push(`- 期間: ${period}`);
  if (serviceName) lines.push(`- サービス名: ${serviceName}`);
  if (serviceId) lines.push(`- サービスID: ${serviceId}`);
  if (orgId) lines.push(`- 組織ID: ${orgId}`);
  if (cmdbId) lines.push(`- CMDB ID: ${cmdbId}`);

  lines.push('');
  lines.push('## 参照');
  if (links.cmdb) lines.push(`- CMDB: ${links.cmdb}`);
  if (links.practice_doc) lines.push(`- プラクティス: ${links.practice_doc}`);
  if (links.usecase_guide) lines.push(`- ユースケース集: ${links.usecase_guide}`);

  lines.push('');
  lines.push('## チェックリスト');
  lines.push('- [ ] 直近の変更・障害・課題を確認');
  lines.push('- [ ] 監視/ダッシュボードの導線を確認');
  lines.push('- [ ] SLA/OLA/契約・合意情報の更新有無を確認');
  lines.push('- [ ] 必要な改善を Issue として分解しリンク');

  return lines.join('\n');
}

function buildLabels(practiceKey, svc) {
  const labels = [];
  labels.push('ITSM');
  labels.push('practice-review');
  labels.push(`practice:${practiceKey}`);
  labels.push(`period:${period}`);

  const serviceId = String(svc.service_id || svc.serviceId || '').trim();
  if (serviceId) labels.push(`service:${serviceId}`);

  const cmdbId = String(svc.cmdb_id || svc.cmdbId || '').trim();
  if (cmdbId) labels.push(`cmdb:${cmdbId}`);

  return labels;
}

const results = [];
let planned = 0;
let created = 0;
let skipped = 0;
let failed = 0;

for (const svc of services) {
  const serviceName = String(svc?.service_name || svc?.serviceName || '').trim();
  const serviceId = String(svc?.service_id || svc?.serviceId || '').trim();
  const orgId = String(svc?.org_id || svc?.orgId || '').trim();
  const cmdbId = String(svc?.cmdb_id || svc?.cmdbId || '').trim();

  if (!orgId || !serviceId || !serviceName) {
    results.push({ ok: false, reason: 'missing service keys', service: { org_id: orgId, service_id: serviceId, service_name: serviceName, cmdb_id: cmdbId } });
    failed += 1;
    continue;
  }

  for (const practiceKey of selectedPracticeKeys) {
    const practice = practiceCatalog[practiceKey];
    const title = `[${period}] ${practice.title}: ${serviceName} (${serviceId})`;
    planned += 1;

    try {
      const existing = await listOpenIssuesBySearch(title);
      const exact = existing.find((i) => String(i?.title || '') === title);
      if (exact) {
        skipped += 1;
        results.push({ ok: true, skipped: true, title, existing_issue_url: exact.web_url || null });
        continue;
      }

      const desc = buildDescription(svc, practice);
      const labels = buildLabels(practiceKey, svc);
      const createdResult = await createIssue(title, desc, labels);
      created += 1;
      results.push(createdResult);
    } catch (e) {
      failed += 1;
      results.push({ ok: false, title, error: String(e?.message || e) });
    }
  }
}

const statusCode = failed > 0 ? 207 : 200;

return [{
  json: {
    ok: failed === 0,
    status_code: statusCode,
    realm,
    project: projectRef,
    period,
    practice_keys: selectedPracticeKeys,
    dry_run: dryRun,
    summary: { planned, created, skipped, failed },
    results
  }
}];
